            double budget = ((Number) project.getOrDefault("budget", 0)).doubleValue();
            String code = (String) project.get("code");
            jdbc.update(
                    "INSERT INTO projects (id, name, client_id, status, archived, budget, code) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    id, project.get("name"), clientId, status, archived, budget, code);
            maxProjectId = Math.max(maxProjectId, id);
        }
        if (maxProjectId > 0) {
            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
        }

        List<Map<String, Object>> contacts =
                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
        long maxContactId = 0;
        for (Map<String, Object> contact : contacts) {
            long id = ((Number) contact.get("id")).longValue();
            long clientId = ((Number) contact.get("clientId")).longValue();
            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
            jdbc.update(
                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary) VALUES (?, ?, ?, ?, ?, ?)",
                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"),
                    primary);
